static Response proxy(const Config&c,const string&host,const string&path,const string&query,const string&method,const Headers&h,const string&body){string ae;for(auto &x:values(h,"accept-encoding")){if(!ae.empty())ae+=",";ae+=x;}string key="http://"+host+path+query;bool auth=!values(h,"authorization").empty();Response r;if(!auth&&(method=="GET"||method=="HEAD")&&cacheget(key,ae,r))return r;string suffix=path.substr(c.proxy.size());string target="/"+suffix+query;size_t idx=rr.fetch_add(1)%c.ups.size();bool timed=false;bool ok=upstream(c,c.ups[idx],method,target,h,body,r,timed);if(!ok&&method!="POST"&&c.ups.size()>1){bool t=false;ok=upstream(c,c.ups[(idx+1)%c.ups.size()],method,target,h,body,r,t);timed=t;}if(!ok)return error(timed?504:502);
 if(method=="GET"&&!auth&&r.status==200&&values(r.h,"set-cookie").empty()){bool pub=false,deny=false,vary=false;long long age=-1;for(auto &v:values(r.h,"cache-control"))for(auto x:split(v,',')){x=lower(trim(x));if(x=="public")pub=true;if(x=="private"||x=="no-store"||x.rfind("private=",0)==0)deny=true;if(x.rfind("max-age=",0)==0){unsigned long long n;if(number(x.substr(8),n))age=(long long)min(n,(unsigned long long)INT_MAX);}}for(auto &v:values(r.h,"vary"))for(auto x:split(v,',')){x=lower(trim(x));if(x=="accept-encoding")vary=true;else deny=true;}if(pub&&!deny&&age>0)cacheput(c,key,ae,vary,min(c.ttl,age*1000),r);}return r;}
static void serve(int fd){Reader r(fd);int count=0;while(!stopping){auto c=atomic_load(&config);long long deadline=nowms()+c->idle;if(r.buf.empty()){if(!r.more(deadline))break;}deadline=nowms()+c->htime;string head;int err=0;for(;;){auto p=r.buf.find("\r\n\r\n");if(p!=string::npos){if(p+4>(size_t)c->hbytes){err=431;break;}head=r.buf.substr(0,p+4);r.buf.erase(0,p+4);break;}if(r.buf.size()>(size_t)c->hbytes){err=431;break;}if(!r.more(deadline)){err=400;break;}}if(err){Response e=error(err);respond(fd,e,false,true,c->wtime);break;}if(head.find('\0')!=string::npos){Response e=error(400);respond(fd,e,false,true,c->wtime);break;}auto p=head.find("\r\n");string line=head.substr(0,p);auto a=line.find(' '),b=a==string::npos?string::npos:line.find(' ',a+1);string method,target,version;Headers h;if(p==string::npos||a==string::npos||b==string::npos||line.find(' ',b+1)!=string::npos||a==0||b==a+1){err=400;}else{method=line.substr(0,a);target=line.substr(a+1,b-a-1);version=line.substr(b+1);if(!token(method)||(version!="HTTP/1.1"&&version!="HTTP/1.0")||!parseheaders(head.substr(p+2),h))err=400;}string path,query,host;if(!err&&!pathdecode(target,path,query))err=400;auto hosts=values(h,"host");if(!err){if(hosts.size()>1||(hosts.empty()&&version=="HTTP/1.1"))err=400;else if(hosts.empty())host=c->defhost;else if(!validhost(hosts[0],host))err=400;else if(host!=c->defhost&&host!=c->bhost)err=400;}
 bool isproxy=!err&&path.rfind(c->proxy,0)==0;auto cl=values(h,"content-length"),te=values(h,"transfer-encoding");unsigned long long len=0;if(!err&&(cl.size()>1||te.size()>1||(!cl.empty()&&!te.empty())||(!cl.empty()&&!number(cl[0],len))))err=400;if(!err&&!isproxy&&(!te.empty()||len))err=400;if(!err&&isproxy&&!te.empty()&&lower(trim(te[0]))!="chunked")err=400;if(!err&&isproxy&&len>(unsigned long long)c->body)err=413;string body;if(!err&&isproxy){if(!te.empty()){if(!chunks(r,body,c->body,deadline,c->hbytes,err)){} }else if(len){if(!r.need(len,deadline))err=400;else{body=r.buf.substr(0,len);r.buf.erase(0,len);}}}
 bool close=version!="HTTP/1.1";for(auto &v:values(h,"connection"))if(hasToken(v,"close"))close=true;count++;if(count>=c->maxreq)close=true;if(err){Response e=error(err);respond(fd,e,method=="HEAD",true,c->wtime);break;}Response out;if(!allowed(c)){out=error(429);out.h.push_back({"Retry-After","1"});}else if(method!="GET"&&method!="HEAD"&&!(isproxy&&method=="POST")){out=error(405);out.h.push_back({"Allow",isproxy?"GET, HEAD, POST":"GET, HEAD"});}else if(isproxy){bool traversal=false;for(auto &x:split(path,'/'))if(x=="..")traversal=true;if(traversal)out=error(403);else out=proxy(*c,host,path,query,method,h,body);}else out=localfile(*c,host,path,query,h,method);if(!respond(fd,out,method=="HEAD",close,c->wtime)||close)break;}close(fd);active--;}
static void* worker(void *p){int fd=(int)(intptr_t)p;serve(fd);return nullptr;}
int main(int argc,char**argv){if(argc!=3||string(argv[1])!="--config")return 1;configfile=argv[2];shared_ptr<Config> c;if(!loadconfig(c))return 1;atomic_store(&config,c);signal(SIGPIPE,SIG_IGN);signal(SIGHUP,sig);signal(SIGTERM,sig);signal(SIGINT,sig);int s=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(s<0)return 1;int one=1;setsockopt(s,SOL_SOCKET,SO_REUSEADDR,&one,sizeof one);if(bind(s,(sockaddr*)&c->listen.sa,sizeof(c->listen.sa))||listen(s,1024)){close(s);return 1;}pthread_attr_t attr;pthread_attr_init(&attr);pthread_attr_setdetachstate(&attr,PTHREAD_CREATE_DETACHED);pthread_attr_setstacksize(&attr,65536);while(!stopping){if(reloadflag.exchange(false)){shared_ptr<Config> n;if(loadconfig(n)&&n->listen.text==c->listen.text){c=n;atomic_store(&config,c);flushcache();}}pollfd p{s,POLLIN,0};int n=poll(&p,1,100);if(n<=0)continue;for(;;){int fd=accept4(s,nullptr,nullptr,SOCK_NONBLOCK|SOCK_CLOEXEC);if(fd<0){if(errno==EINTR)continue;break;}if(active.load()>=c->maxconn){close(fd);continue;}active++;pthread_t t;if(pthread_create(&t,&attr,worker,(void*)(intptr_t)fd)){active--;close(fd);}}}close(s);long long until=nowms()+c->drain;while(active.load()&&nowms()<until)usleep(10000);return 0;}
